<script setup lang="ts">
import {onMounted,ref,watch} from "vue";
import {request,query,type Page,type CustomerConfiguration} from "@papilio/api";
import {faDate,faNumber} from "@papilio/ui";
import {useAuth} from "@papilio/auth";
import {useI18n} from "vue-i18n";
const props=defineProps<{customerId:number;subscriptionId?:number}>();
const auth=useAuth(),{t}=useI18n(),rows=ref<CustomerConfiguration[]>([]),page=ref(1),pages=ref(1),total=ref(0),loading=ref(false),error=ref("");
let sequence=0;
async function load():Promise<void>{const token=++sequence;loading.value=true;error.value="";try{const result=await request<Page<CustomerConfiguration>>(`/v1/admin/customers/${props.customerId}/configurations?${query({page:page.value,subscription_id:props.subscriptionId})}`);if(token!==sequence)return;rows.value=result.data;pages.value=result.meta.pager?.total_pages??1;total.value=result.meta.pager?.total_items??0;}catch(cause){if(token===sequence)error.value=cause instanceof Error?cause.message:t("customerConfigurations.loadFailed");}finally{if(token===sequence)loading.value=false;}}
watch(()=>[props.customerId,props.subscriptionId],()=>{page.value=1;rows.value=[];void load();});onMounted(load);
</script>
<template><section class="card card-pad"><div class="page-head"><div><p class="eyebrow">{{ t('customerConfigurations.eyebrow') }}</p><h2>{{ t('customerConfigurations.title') }} <span class="badge">{{faNumber(total)}}</span></h2></div><button class="btn small secondary" :disabled="loading" @click="load">{{ t('customerConfigurations.refresh') }}</button></div><p v-if="error" class="message error" role="alert">{{error}}</p><p v-else-if="loading" class="empty">{{ t('customerConfigurations.loading') }}</p><p v-else-if="!rows.length" class="empty">{{ t('customerConfigurations.empty') }}</p><article v-for="row in rows" :key="row.profile_id" class="configuration-item"><div class="configuration-meta"><h4>{{row.configuration_label}}</h4><span class="bundle-tag">{{row.protocol}}</span><span class="badge" :class="row.status==='active'?'success':'warning'">{{row.status.replaceAll('_',' ')}}</span></div><p>{{row.plan_title}} · {{row.node_label}} · {{ t('customerConfigurations.subscriptionId', { id: faNumber(row.subscription_id) }) }}</p><div class="configuration-meta"><span class="bundle-tag">{{row.quota_bytes===null?t('customerConfigurations.unlimited'):faNumber(row.quota_bytes/1_073_741_824)+' GiB'}} · {{faDate(row.expires_at)}}</span><span class="bundle-tag">{{row.applied_revision===row.desired_revision?t('customerConfigurations.appliedRevision', { revision: faNumber(row.desired_revision) }):t('customerConfigurations.awaitingRevision', { revision: faNumber(row.desired_revision) })}}</span></div><div class="inline-actions" style="margin-top:12px"><RouterLink v-if="auth.can('subscriptions')" class="btn small secondary" :to="{path:'/subscriptions',query:{customer_id:row.customer_id,subscription_id:row.subscription_id}}">{{ t('customerConfigurations.viewSubscription') }}</RouterLink><RouterLink class="btn small secondary" :to="`/network/${row.node_id}/configurations?configuration_id=${row.configuration_id}`">{{ t('customerConfigurations.manageConfiguration') }}</RouterLink></div></article><div class="pager"><button :disabled="loading||page<=1" :aria-label="t('customerPicker.previous')" @click="page--;load()">‹</button><span>{{faNumber(page)}} / {{faNumber(pages)}}</span><button :disabled="loading||page>=pages" :aria-label="t('customerPicker.next')" @click="page++;load()">›</button></div></section></template>
